package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen0Test {

    @Test
    public void testIsNumber_NullAndEmpty() {
        assertFalse("Null should return false", NumberUtils.isNumber(null));
        assertFalse("Empty string should return false", NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_Integers() {
        assertTrue("Positive integer", NumberUtils.isNumber("123"));
        assertTrue("Negative integer", NumberUtils.isNumber("-123"));
        assertTrue("Zero", NumberUtils.isNumber("0"));
        assertTrue("Integer with sign", NumberUtils.isNumber("+123"));
        assertFalse("Only sign", NumberUtils.isNumber("-"));
        assertFalse("Only plus", NumberUtils.isNumber("+"));
    }

    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal", NumberUtils.isNumber("123.45"));
        assertTrue("Decimal with sign", NumberUtils.isNumber("-123.45"));
        assertTrue("Decimal starting with dot", NumberUtils.isNumber(".45"));
        assertTrue("Decimal ending with dot", NumberUtils.isNumber("123."));
        assertFalse("Multiple dots", NumberUtils.isNumber("1.2.3"));
        assertFalse("Dot without digits", NumberUtils.isNumber("."));
    }

    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Hex lowercase", NumberUtils.isNumber("0x1a"));
        assertTrue("Hex uppercase", NumberUtils.isNumber("0x1A"));
        assertTrue("Hex with sign", NumberUtils.isNumber("-0x1A"));
        assertTrue("Hex with max digit", NumberUtils.isNumber("0xFF"));
        assertFalse("Empty hex", NumberUtils.isNumber("0x"));
        assertFalse("Invalid hex char", NumberUtils.isNumber("0xG"));
        assertFalse("Hex with decimal", NumberUtils.isNumber("0x1.2"));
    }

    @Test
    public void testIsNumber_ScientificNotation() {
        assertTrue("Scientific notation", NumberUtils.isNumber("1e10"));
        assertTrue("Scientific notation uppercase", NumberUtils.isNumber("1E10"));
        assertTrue("Scientific with negative exponent", NumberUtils.isNumber("1e-10"));
        assertTrue("Scientific with positive exponent sign", NumberUtils.isNumber("1e+10"));
        assertTrue("Scientific decimal", NumberUtils.isNumber("1.23e4"));
        assertTrue("Scientific negative base", NumberUtils.isNumber("-1.23e4"));

        assertFalse("E without digits before", NumberUtils.isNumber("e10"));
        assertFalse("E without digits after", NumberUtils.isNumber("1e"));
        assertFalse("E with sign but no digits after", NumberUtils.isNumber("1e-"));
        assertFalse("Two Es", NumberUtils.isNumber("1e2e3"));
        assertFalse("Dot in exponent", NumberUtils.isNumber("1e1.2"));
    }

    @Test
    public void testIsNumber_TypeQualifiers() {
        // Test d, D, f, F
        assertTrue("Integer suffix d", NumberUtils.isNumber("123d"));
        assertTrue("Integer suffix D", NumberUtils.isNumber("123D"));
        assertTrue("Float suffix f", NumberUtils.isNumber("123.4f"));
        assertTrue("Float suffix F", NumberUtils.isNumber("123.4F"));

        // Test l, L
        assertTrue("Long suffix l", NumberUtils.isNumber("123l"));
        assertTrue("Long suffix L", NumberUtils.isNumber("123L"));

        // Negative cases for qualifiers
        assertFalse("Suffix with exponent L", NumberUtils.isNumber("1e2l"));
        assertFalse("Suffix with exponent L uppercase", NumberUtils.isNumber("1E2L"));
        assertFalse("Invalid suffix", NumberUtils.isNumber("123x"));

        // Ensure foundDigit requirement for suffixes
        assertFalse("Suffix without digits", NumberUtils.isNumber("f"));
    }

    @Test
    public void testIsNumber_EdgeCases() {
        // Testing the logic for i < sz + 1 && allowSigns && !foundDigit
        // This covers cases where a sign follows an 'E' but no digit has been found yet
        assertFalse("Sign after E with no digits", NumberUtils.isNumber("1E-"));

        // Testing the branch for i < chars.length at the end
        assertTrue("Single digit", NumberUtils.isNumber("5"));

        // Testing character-by-character logic for non-numeric chars
        assertFalse("String with space", NumberUtils.isNumber("12 3"));
        assertFalse("String with alpha", NumberUtils.isNumber("12a3"));
    }
}
